        n = len(f)
        if n == 1:
            return 1
        minterms = set()
        for i in range(2**n):
            if f[i] == 0:
                continue
            minterm = []
            for j in range(n):
                if (i >> j) & 1:
                    minterm.append(j)
            minterms.add(tuple(sorted(minterm)))
        width = 0
        while minterms:
            new_minterms = set()
            for m in minterms:
                if len(m) == 1:
                    continue
                v = m[0]
                new_minterms.update({tuple(sorted([x for x in m if x != v]))})
            width += 1
            minterms = new_minterms
        return width

    def symplectic_leaves(f):
        n = len(f)
        leaves = set()
        for i in range(2**n):
